from uuid import UUID

import pytest
from fastapi import FastAPI, Request, WebSocket
from fastapi.testclient import TestClient


def test_request_id_header():
    app = FastAPI(add_request_id_header=True)

    @app.get("/")
    async def get_request_id(request: Request):
        return {"request_id": request.state.request_id}

    with TestClient(app) as client:
        response = client.get("/", headers={"X-Request-ID": "client-provided"})
        second_response = client.get("/")

    assert response.status_code == 200
    assert "X-Request-ID" in response.headers
    request_id = response.headers["X-Request-ID"]
    assert UUID(request_id).version == 4
    assert str(UUID(request_id)) == request_id
    assert response.json() == {"request_id": request_id}
    assert second_response.headers["X-Request-ID"] != request_id


@pytest.mark.parametrize("options", [{}, {"add_request_id_header": False}])
def test_request_id_disabled(options):
    app = FastAPI(**options)

    @app.get("/")
    async def get_request_id(request: Request):
        return {"has_request_id": hasattr(request.state, "request_id")}

    response = TestClient(app).get("/")
    assert "X-Request-ID" not in response.headers
    assert response.json() == {"has_request_id": False}


@pytest.mark.parametrize("path, status_code", [("/missing", 404), ("/error", 500)])
def test_request_id_error_response(path, status_code):
    app = FastAPI(add_request_id_header=True)

    @app.get("/error")
    async def error():
        raise RuntimeError("Internal error")

    response = TestClient(app, raise_server_exceptions=False).get(path)
    assert response.status_code == status_code
    assert UUID(response.headers["X-Request-ID"]).version == 4


def test_request_id_websocket():
    app = FastAPI(add_request_id_header=True)

    @app.websocket("/ws")
    async def websocket_endpoint(websocket: WebSocket):
        await websocket.accept()
        await websocket.send_json(
            {"has_request_id": hasattr(websocket.state, "request_id")}
        )
        await websocket.close()

    with TestClient(app) as client, client.websocket_connect("/ws") as websocket:
        assert websocket.receive_json() == {"has_request_id": False}
